// the error).
func GomModuleFromStream(stream io.Reader) (GomModule, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return GomModuleFromTerm(at), nil
}

