var _ sl.Strategy = (*IsConcArg)(nil)

// VisitConcArg is the `_ConcArg` slot-visit strategy: when subject is `ConcArg`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `ConcArg`.
type VisitConcArg struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitConcArg builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitConcArg(args ...sl.Strategy) *VisitConcArg {
	return &VisitConcArg{args: args}
}

func (s *VisitConcArg) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcArgArgList); !ok {
		return subject, sl.ErrVisitFailure
	}
	// Variadic alt: visit every element with args[0] (Java's
	// `_concX` invokes the sub-strategy on each list element).
	if len(s.args) == 0 {
		return subject, nil
	}
	count := intro.GetChildCount(subject)
	var newChildren []any
	for i := 0; i < count; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[0].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitConcArg) ChildCount() int                 { return len(s.args) }
func (s *VisitConcArg) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitConcArg) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitConcArg) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcArgArgList); !ok {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, true)
}
func (s *VisitConcArg) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitConcArg) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitConcArg)(nil)

// SymbolName is the symbol of the Java term: ConsConcArg or EmptyConcArg.
func (t *ConcArgArgList) SymbolName() string {
	if t.empty {
		return "EmptyConcArg"
	}
	return "ConsConcArg"
}

func (t *ConcArgArgList) IsConsConcArg() bool  { return !t.empty }
func (t *ConcArgArgList) IsEmptyConcArg() bool { return t.empty }

func (t *ConcArgArgList) GetHeadConcArg() Arg {
	if t.empty {
		panic(&aterm.GomError{Msg: "This ArgList has no HeadConcArg"})
	}
	return t.head
}
func (t *ConcArgArgList) GetTailConcArg() ArgList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This ArgList has no TailConcArg"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a ConcArg list counts as one element).
func (t *ConcArgArgList) Length() int {
	res := 0
	var tl ArgList = t
	for {
		c, ok := tl.(*ConcArgArgList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcArgArgList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a ConcArg list.
func (t *ConcArgArgList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur ArgList = t
	for {
		c, ok := cur.(*ConcArgArgList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcArgArgList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcArg
// (through the hooks).
func (t *ConcArgArgList) Reverse() ArgList {
	if t.empty {
		return t
	}
	var cur ArgList = t
	var rev ArgList = EmptyConcArg()
	for {
		c, ok := cur.(*ConcArgArgList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcArg(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcArg (through the hooks).
func (t *ConcArgArgList) Append(element Arg) ArgList {
	var heads []Arg
	var cur ArgList = t
	for {
		c, ok := cur.(*ConcArgArgList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res ArgList
	if c, ok := cur.(*ConcArgArgList); ok && c.empty {
		res = ConsConcArg(element, cur)
	} else {
		res = ConsConcArg(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcArg(heads[i], res)
	}
	return res
}

func (t *ConcArgArgList) CompareTo(o any) int {
	for {
		ao := o.(ArgList)
		if ao == ArgList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcArgArgList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcArgArgList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcArgArgList) CompareToLPO(o any) int {
	for {
		ao := o.(ArgList)
		if ao == ArgList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcArgArgList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcArgArgList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcArgArgList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Arg
	var cur ArgList = t
	for {
		c, ok := cur.(*ConcArgArgList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcArgArgList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcArgArgList is Java Gom's ConcArg.fromTerm: an application of ConcArg, or a
// list (of ToATerm), of convertible elements.
func fromTermConcArgArgList(trm aterm.ATerm, conv aterm.ATermConverter) (res ArgList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "ConcArg" {
		elems := make([]Arg, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = ArgFromTermConv(a, conv)
		}
		return MakeConcArg(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a ConcArg (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Arg
		for !list.IsEmpty() {
			elems = append(elems, ArgFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcArg(elems...), true
	}
	return nil, false
}

