	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ModuleModule)
	if c := t.MDecl.CompareToLPO(tco.MDecl); c != 0 {
		return c
	}
	if c := t.Sorts.CompareToLPO(tco.Sorts); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
